#include "mgt_cuda/bf16_batch_norm_epilogue.cuh"
#include <cmath>
#include <cstdint>
#include <vector>
using mgt_cuda::LaunchBf16BatchNormBackwardEpilogue;
using mgt_cuda::LaunchBf16BatchNormForwardEpilogue;
int main(){constexpr unsigned cap=3,active=2,physical=64,logical=35;const std::size_t n=(std::size_t)cap*physical,words=cap*2;std::vector<float>x(n,9),up(n,2),mean(physical,1),inv(physical,.5f),gamma(physical,2),beta(physical,-1),dg(physical,0),db(physical,1);for(unsigned r=0;r<active;++r)for(unsigned c=0;c<logical;++c)x[r*physical+c]=(c%3==0)?1:5;float *dx,*du,*dm,*di,*dgamma,*dbeta,*xhat,*skip;__nv_bfloat16 *act,*dz;unsigned*mask;if(cudaMalloc(&dx,n*4)||cudaMalloc(&du,n*4)||cudaMalloc(&dm,physical*4)||cudaMalloc(&di,physical*4)||cudaMalloc(&dgamma,physical*4)||cudaMalloc(&dbeta,physical*4)||cudaMalloc(&xhat,n*4)||cudaMalloc(&skip,n*4)||cudaMalloc(&act,n*2)||cudaMalloc(&dz,n*2)||cudaMalloc(&mask,words*4))return 1;cudaMemcpy(dx,x.data(),n*4,cudaMemcpyHostToDevice);cudaMemcpy(du,up.data(),n*4,cudaMemcpyHostToDevice);cudaMemcpy(dm,mean.data(),physical*4,cudaMemcpyHostToDevice);cudaMemcpy(di,inv.data(),physical*4,cudaMemcpyHostToDevice);cudaMemcpy(dgamma,gamma.data(),physical*4,cudaMemcpyHostToDevice);cudaMemcpy(dbeta,beta.data(),physical*4,cudaMemcpyHostToDevice);if(LaunchBf16BatchNormForwardEpilogue(dx,dm,di,dgamma,dbeta,nullptr,active,cap,logical,physical,mgt::A100XhatStorage::kFp32,xhat,act,mask,0)!=mgt::Status::kOk)return 2;cudaMemcpy(dgamma,dg.data(),physical*4,cudaMemcpyHostToDevice);cudaMemcpy(dbeta,db.data(),physical*4,cudaMemcpyHostToDevice);if(LaunchBf16BatchNormBackwardEpilogue(du,mask,xhat,di,(const float*)nullptr,dgamma,dbeta,active,cap,active,logical,physical,mgt::A100XhatStorage::kFp32,dz,skip,0)!=mgt::Status::kInvalidConfig)return 3;cudaMemcpy(dgamma,gamma.data(),physical*4,cudaMemcpyHostToDevice);if(LaunchBf16BatchNormBackwardEpilogue(du,mask,xhat,di,dgamma,dg.empty()?nullptr:dgamma,dbeta,active,cap,active,logical,physical,mgt::A100XhatStorage::kFp32,dz,skip,0)!=mgt::Status::kOk||cudaDeviceSynchronize())return 4;std::vector<__nv_bfloat16>ha(n),hz(n);std::vector<float>hs(n);std::vector<unsigned>hm(words);cudaMemcpy(ha.data(),act,n*2,cudaMemcpyDeviceToHost);cudaMemcpy(hz.data(),dz,n*2,cudaMemcpyDeviceToHost);cudaMemcpy(hs.data(),skip,n*4,cudaMemcpyDeviceToHost);cudaMemcpy(hm.data(),mask,words*4,cudaMemcpyDeviceToHost);for(unsigned r=0;r<cap;++r)for(unsigned c=0;c<physical;++c){bool valid=r<active&&c<logical,on=valid&&c%3!=0;if(((hm[r*2+c/32]>>(c&31))&1U)!=on)return 5;if(std::fabs((float)ha[r*physical+c]-(on?3.0f:0.0f))>.01f)return 6;if(std::fabs(hs[r*physical+c]-(on?2.0f:0.0f))>1e-6f)return 7;if(!std::isfinite((float)hz[r*physical+c]))return 8;if(std::fabs((float)hz[r*physical+c]-(valid?-0.5f:0.0f))>.01f)return 12;}if(LaunchBf16BatchNormForwardEpilogue(dx,dm,di,dgamma,dbeta,nullptr,active,cap,logical,physical,mgt::A100XhatStorage::kBf16,xhat,act,mask,0)!=mgt::Status::kOk)return 9;if(LaunchBf16BatchNormBackwardEpilogue(du,mask,xhat,di,dgamma,dgamma,dbeta,active,cap,active,logical,physical,mgt::A100XhatStorage::kBf16,dz,skip,0)!=mgt::Status::kOk||cudaDeviceSynchronize())return 10;cudaMemcpy(hz.data(),dz,n*2,cudaMemcpyDeviceToHost);for(auto v:hz)if(!std::isfinite((float)v))return 11;cudaFree(mask);cudaFree(dz);cudaFree(act);cudaFree(skip);cudaFree(xhat);cudaFree(dbeta);cudaFree(dgamma);cudaFree(di);cudaFree(dm);cudaFree(du);cudaFree(dx);return 0;}
